public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the maximum length among all strings
    int maxLen = 0;
    for (String s : strings) {
        if (s != null) {
            maxLen = Math.max(maxLen, s.length());
        }
    }
    // If no string has positive length, no substring possible
    if (maxLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    if (first == null) {
        first = "";
    }
    for (int len = maxLen; len >= 1; len--) {
        // Gather unique substrings of length len from the first string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            candidates.add(first.substring(i, i + len));
        }
        // For each candidate, check all strings
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String t : strings) {
                if (t == null) {
                    ok = false;
                    break;
                }
                if (!t.contains(cand) && !t.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to limit candidate substrings
    String minStr = null;
    for (String s : strings) {
        if (s == null) continue; // ignore null entries
        if (minStr == null || s.length() < minStr.length()) {
            minStr = s;
        }
    }
    if (minStr == null || minStr.isEmpty()) {
        return 0;
    }
    int minLen = minStr.length();
    for (int len = minLen; len >= 1; len--) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (int start = 0; start <= minLen - len; start++) {
            String candidate = minStr.substring(start, start + len);
            if (!seen.add(candidate)) {
                continue; // skip duplicate substrings of this length
            }
            String rev = new java.lang.StringBuilder(candidate).reverse().toString();
            boolean allMatch = true;
            for (String s : strings) {
                if (s == null) {
                    allMatch = false;
                    break;
                }
                if (!s.contains(candidate) && !s.contains(rev)) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to limit the candidate space
    String shortest = strings.get(0);
    for (String s : strings) {
        if (s.length() < shortest.length()) {
            shortest = s;
        }
    }

    int best = 0;
    int m = shortest.length();

    // Generate all substrings of the shortest string
    for (int i = 0; i < m; i++) {
        for (int j = i + 1; j <= m; j++) {
            String sub = shortest.substring(i, j);
            int len = 0;
            // Skip if this length cannot beat the current best
            len = j - i;
            if (len <= best) {
                continue;
            }

            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            // Check all strings: each must contain sub or rev
            for (String t : strings) {
                if (!(t.contains(sub) || t.contains(rev))) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                best = len;
            }
        }
    }

    return best;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int minLen = first.length();
    for (int i = 1; i < strings.size(); i++) {
        minLen = Math.min(minLen, strings.get(i).length());
    }
    // Iterate from longest possible length downwards
    for (int len = minLen; len >= 1; len--) {
        // Build set of candidate substrings from first string (including reverses)
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (int start = 0; start <= first.length() - len; start++) {
            String sub = first.substring(start, start + len);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
        // Check each candidate against all strings
        outer:
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            for (int idx = 0; idx < strings.size(); idx++) {
                String s = strings.get(idx);
                boolean contains = s.contains(cand);
                if (!contains && !s.contains(rev)) {
                    continue outer; // candidate fails for this string
                }
            }
            // candidate satisfies all strings
            return len;
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null) {
        return 0;
    }
    int rows = grid.length;
    if (rows == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][];
    for (int r = 0; r < rows; r++) {
        visited[r] = new boolean[grid[r].length];
    }

    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        int cols = grid[r].length;
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                java.util.Stack<int[]> stack = new java.util.Stack<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int pr = pos[0];
                    int pc = pos[1];

                    for (int d = 0; d < 8; d++) {
                        int nr = pr + dr[d];
                        int nc = pc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return count;
}

