public static int maxRegions(int N) {
    if (N <= 0) {
        return 1; // No triangles, the whole plane is one region
    }
    long regions = 3L * N * (N - 1) + 2L; // 3n(n-1)+2
    return (int) regions;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // no triangles, the plane is one region
    }
    long result = 3L * N * (N - 1) + 2;
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) result;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1;
    }
    long regions = 3L * N * N - 3L * N + 2L;
    return (int) regions;
}

