public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Set<Integer> allNumbers = new java.util.HashSet<>();
    for (int num : numbers) {
        allNumbers.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 == 0 && allNumbers.contains(num / 2)) {
            count++;
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int n = entry.getKey();
        if (n % 2 != 0) continue;
        int half = n / 2;
        Integer fHalf = freq.get(half);
        if (fHalf != null) {
            if (half == n) { // only possible for n == 0
                if (fHalf > 1) {
                    count += entry.getValue();
                }
            } else {
                count += entry.getValue();
            }
        }
    }
    return count;
}

