public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // Helper to convert coordinate array to a string key
    java.util.function.Function<int[], String> toKey = coords -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coords.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coords[i]);
        }
        return sb.toString();
    };
    String startKey = toKey.apply(start);
    String endKey = toKey.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            continue; // skip invalid path entry
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String keyA = toKey.apply(a);
        String keyB = toKey.apply(b);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    // BFS traversal
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors == null) {
            continue;
        }
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique key
    java.util.function.Function<int[], String> keyFunc = coord -> coord[0] + "," + coord[1];
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    // Build adjacency list from paths
    for (int[] p : paths) {
        if (p.length != 4) continue; // skip invalid path specification
        int sx = p[0], sy = p[1], dx = p[2], dy = p[3];
        if (sx < 0 || sx >= n || sy < 0 || sy >= n || dx < 0 || dx >= n || dy < 0 || dy >= n) continue;
        String sKey = keyFunc.apply(new int[]{sx, sy});
        String dKey = keyFunc.apply(new int[]{dx, dy});
        graph.computeIfAbsent(sKey, k -> new java.util.ArrayList<>()).add(dKey);
        graph.computeIfAbsent(dKey, k -> new java.util.ArrayList<>()).add(sKey);
    }

    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);

    if (startKey.equals(endKey)) return "can be travelled";

    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = graph.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
