        System.arraycopy(p, n, to, 0, n);
        String fromKey = keyGen.apply(from);
        String toKey = keyGen.apply(to);
        adjacency.computeIfAbsent(fromKey, k -> new java.util.ArrayList<>()).add(toKey);
        adjacency.computeIfAbsent(toKey, k -> new java.util.ArrayList<>()).add(fromKey);
    }

    String startKey = keyGen.apply(start);
    String endKey = keyGen.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
