}

public static String convertDatesToWeekdays(String date) {
    try {
        java.time.format.DateTimeFormatter inputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy").withLocale(java.util.Locale.ENGLISH);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);

        java.time.format.DateTimeFormatter outputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy").withLocale(java.util.Locale.ENGLISH);
        String dateString = localDate.format(outputFormatter);

        java.time.format.TextStyle weekdayStyle = java.time.format.TextStyle.FULL;
        String weekday = localDate.getDayOfWeek().getDisplayName(weekdayStyle, java.util.Locale.ENGLISH);

        return dateString + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        // Invalid input format; return null to indicate failure
        return null;
    }
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split("\\s+");
    if (parts.length != 3) {
        return "Invalid date format";
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        java.time.Month monthObj = localDate.getMonth();
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();

        String monthName = monthObj.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String dayName = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return monthName + " " + day + ", " + year + " is a " + dayName;
    } catch (Exception e) {
        return "Invalid date";
    }
}

