public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) return false;
    if (arr.length % 2 != 0) return false; // cannot form pairs

    if (k <= 0) return false; // divisor must be positive

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) return false;

    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // Check other remainders
    for (int r = 1; r < k; r++) {
        // Skip the complementary pair already processed
        if (r == k - r) continue; // this case handled above
        if (freq[r] != freq[k - r]) return false;
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k);
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) {
            if (count[i] % 2 != 0) {
                return false;
            }
        } else {
            if (count[i] != count[j]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null.");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be positive.");
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair an odd number of elements
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = Math.floorMod(num, k); // handles negative numbers correctly
        freq[rem]++;
    }
    // Remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also be even
    if (k % 2 == 0 && (freq[k / 2] % 2 != 0)) {
        return false;
    }
    // Check other remainder pairs
    for (int r = 1; r <= (k - 1) / 2; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k == 0) return false;
    int absK = Math.abs(k);
    int[] remainderCount = new int[absK];
    for (int num : arr) {
        int r = ((num % absK) + absK) % absK;
        remainderCount[r]++;
    }
    // Check remainder 0
    if (remainderCount[0] % 2 != 0) return false;
    // If k is even, middle remainder (k/2) must have even count
    if (absK % 2 == 0) {
        int mid = absK / 2;
        if (remainderCount[mid] % 2 != 0) return false;
    }
    // For other remainders, counts must match complementary remainder
    for (int r = 1; r < absK; r++) {
        if (r != absK - r && remainderCount[r] != remainderCount[absK - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if ((n & 1) == 1) { // odd length can't form pairs
        return false;
    }

    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }

    // remainder 0 must be even
    if ((count[0] & 1) == 1) {
        return false;
    }

    // if k is even, remainder k/2 must be even
    if ((k & 1) == 0) {
        int half = k / 2;
        if ((count[half] & 1) == 1) {
            return false;
        }
    }

    // check other pairs of remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // handled k/2 case above
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }

    return true;
}

