public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Basic validation
    if (n <= 0) {
        return 0;
    }
    if (hasApple == null) {
        return 0;
    }
    // Build adjacency list
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length < 2) {
                continue;
            }
            int u = e[0];
            int v = e[1];
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adj[u].add(v);
                adj[v].add(u);
            }
        }
    }
    final int[] time = new int[1];
    class DFS {
        boolean visit(int node, int parent) {
            boolean has = node < hasApple.length && hasApple[node];
            for (int nei : adj[node]) {
                if (nei == parent) {
                    continue;
                }
                if (visit(nei, node)) {
                    time[0] += 2;
                    has = true;
                }
            }
            return has;
        }
    }
    new DFS().visit(0, -1);
    return time[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    boolean[] visited = new boolean[n];
    int[] total = new int[1];

    class DFS {
        boolean dfs(int node) {
            visited[node] = true;
            boolean has = hasApple[node];
            for (int nei : graph[node]) {
                if (!visited[nei]) {
                    boolean childHas = dfs(nei);
                    if (childHas) {
                        total[0] += 2;
                        has = true;
                    }
                }
            }
            return has;
        }
    }

    new DFS().dfs(0);
    return total[0];
}

