}

public String sortString(String s) {
    TreeMap<Character, Integer> map = new TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder res = new StringBuilder();
    int left = s.length();
    while (left > 0 && !map.isEmpty()) {
        // Ascending pass
        char curr = map.firstKey();
        res.append(curr);
        int cnt = map.get(curr);
        if (cnt == 1) {
            map.remove(curr);
        } else {
            map.put(curr, cnt - 1);
        }
        left--;
        char last = curr;
        while (true) {
            Character nextKey = map.higherKey(last);
            if (nextKey == null) {
                break;
            }
            curr = nextKey;
            res.append(curr);
            int c = map.get(curr);
            if (c == 1) {
                map.remove(curr);
            } else {
                map.put(curr, c - 1);
            }
            left--;
            last = curr;
        }
        if (left == 0) {
            break;
        }

        // Descending pass
        curr = map.lastKey();
        res.append(curr);
        int c = map.get(curr);
        if (c == 1) {
            map.remove(curr);
        } else {
            map.put(curr, c - 1);
        }
        left--;
        char lastDesc = curr;
        while (true) {
            Character prevKey = map.lowerKey(lastDesc);
            if (prevKey == null) {
                break;
            }
            curr = prevKey;
            res.append(curr);
            int cc = map.get(curr);
            if (cc == 1) {
                map.remove(curr);
            } else {
                map.put(curr, cc - 1);
            }
            left--;
            lastDesc = curr;
        }
    }
    return res.toString();
}

public String sortString(String s) {
    int[] freq = new int[256];
    for (char ch : s.toCharArray()) {
        freq[ch]++;
    }
    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Increasing phase
        int i = 0;
        while (i < 256 && freq[i] == 0) {
            i++;
        }
        if (i == 256) {
            break;
        }
        char last = (char) i;
        result.append(last);
        freq[i]--;
        remaining--;

        // Continue selecting smallest characters greater than the last appended
        for (int j = i + 1; j < 256; j++) {
            while (freq[j] > 0) {
                last = (char) j;
                result.append(last);
                freq[j]--;
                remaining--;
            }
        }

        // Decreasing phase
        i = 255;
        while (i >= 0 && freq[i] == 0) {
            i--;
        }
        if (i < 0) {
            break;
        }
        last = (char) i;
        result.append(last);
        freq[i]--;
        remaining--;

        // Continue selecting largest characters smaller than the last appended
        for (int j = i - 1; j >= 0; j--) {
            while (freq[j] > 0) {
                last = (char) j;
                result.append(last);
                freq[j]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        if (c >= 'a' && c <= 'z') {
            count[c - 'a']++;
        } else if (c >= 'A' && c <= 'Z') {
            count[c - 'A']++; // treat uppercase as lowercase for counting
        } else {
            // ignore non-alphabetic characters
        }
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (total > 0) {
        // Ascending scan: pick smallest and subsequent greater characters
        int lastIdx = -1;
        for (int i = 0; i < 26 && total > 0; i++) {
            if (count[i] == 0) {
                continue;
            }
            result.append((char) ('a' + i));
            count[i]--;
            total--;
            lastIdx = i;
            break;
        }
        for (int j = lastIdx + 1; j < 26 && total > 0; j++) {
            if (count[j] == 0) {
                continue;
            }
            result.append((char) ('a' + j));
            count[j]--;
            total--;
            lastIdx = j;
        }
        if (total == 0) {
            break;
        }
        // Descending scan: pick largest and subsequent smaller characters
        for (int i = 25; i >= 0 && total > 0; i--) {
            if (count[i] == 0) {
                continue;
            }
            result.append((char) ('a' + i));
            count[i]--;
            total--;
            lastIdx = i;
            break;
        }
        for (int j = lastIdx - 1; j >= 0 && total > 0; j--) {
            if (count[j] == 0) {
                continue;
            }
            result.append((char) ('a' + j));
            count[j]--;
            total--;
            lastIdx = j;
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null) return null;
    if (s.isEmpty()) return "";
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder res = new StringBuilder();
    while (!map.isEmpty()) {
        // Pick smallest character
        java.util.Map.Entry<Character, Integer> first = map.firstEntry();
        char last = first.getKey();
        res.append(last);
        map.merge(last, -1, Integer::sum);
        if (map.get(last) == 0) map.remove(last);
        // Pick increasing characters
        while (true) {
            java.util.Map.Entry<Character, Integer> higher = map.higherEntry(last);
            if (higher == null) break;
            last = higher.getKey();
            res.append(last);
            map.merge(last, -1, Integer::sum);
            if (map.get(last) == 0) map.remove(last);
        }
        // If no more characters left, break
        if (map.isEmpty()) break;
        // Pick largest character
        java.util.Map.Entry<Character, Integer> lastEntry = map.lastEntry();
        last = lastEntry.getKey();
        res.append(last);
        map.merge(last, -1, Integer::sum);
        if (map.get(last) == 0) map.remove(last);
        // Pick decreasing characters
        while (true) {
            java.util.Map.Entry<Character, Integer> lower = map.lowerEntry(last);
            if (lower == null) break;
            last = lower.getKey();
            res.append(last);
            map.merge(last, -1, Integer::sum);
            if (map.get(last) == 0) map.remove(last);
        }
    }
    return res.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int num : nums) total += num;
    int maxk = n / 2;
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] sums = new java.util.HashSet[maxk + 1];
    for (int i = 0; i <= maxk; i++) {
        sums[i] = new java.util.HashSet<>();
    }
    for (int val : nums) {
        for (int k = maxk; k >= 1; k--) {
            java.util.Set<Integer> prev = sums[k - 1];
            java.util.Set<Integer> current = sums[k];
            for (int s : prev) {
                current.add(s + val);
            }
        }
    }
    for (int k = 1; k <= maxk; k++) {
        if ((total * k) % n == 0) {
            int target = (total * k) / n;
            if (sums[k].contains(target)) return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long total = 0;
    for (int num : nums) total += num;
    int maxK = n / 2;
    java.util.HashSet<Integer>[] subsets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) subsets[i] = new java.util.HashSet<>();
    subsets[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            java.util.HashSet<Integer> prev = subsets[k - 1];
            if (prev.isEmpty()) continue;
            java.util.HashSet<Integer> curr = subsets[k];
            for (int sum : prev) {
                curr.add(sum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((total * k) % n != 0) continue;
        int target = (int) (total * k / n);
        if (subsets[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int v : nums) sum += v;
    // DP table: dp[k][s] == true if a subset of size k with sum s exists
    boolean[][] dp = new boolean[n + 1][sum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= sum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((sum * k) % n != 0) continue;
        int target = (sum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Build subset sums for each possible size
    java.util.HashSet<Integer>[] sumSets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumSets[i] = new java.util.HashSet<>();
    }
    sumSets[0].add(0);

    for (int num : nums) {
        // Iterate sizes in reverse to avoid reusing the same number in a single iteration
        for (int size = n - 1; size >= 0; size--) {
            java.util.HashSet<Integer> currentSet = sumSets[size];
            java.util.HashSet<Integer> nextSet = sumSets[size + 1];
            for (int s : currentSet) {
                nextSet.add(s + num);
            }
        }
    }

    // Check for each possible subset size k if a valid partition exists
    for (int k = 1; k <= n - 1; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue; // Target sum not integer, skip this k
        }
        int target = (int) (product / n);
        if (sumSets[k].contains(target)) {
            return true; // Found a valid split
        }
    }

    return false; // No valid split found
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int half = n / 2;
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[half + 1];
    for (int i = 0; i <= half; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        for (int k = half; k >= 1; k--) {
            for (int sumPrev : dp[k - 1]) {
                dp[k].add(sumPrev + num);
            }
        }
    }
    for (int k = 1; k <= half; k++) {
        if ((totalSum * k) % n == 0) {
            int target = (totalSum * k) / n;
            if (dp[k].contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start from step 1 (outside the array) and reach the top with no cost
        return 0;
    }
    int dpPrevPrev = cost[0];   // dp[0]
    int dpPrev = cost[1];       // dp[1]
    int dpCurr = 0;
    for (int i = 2; i < n; i++) {
        dpCurr = cost[i] + Math.min(dpPrev, dpPrevPrev);
        dpPrevPrev = dpPrev;
        dpPrev = dpCurr;
    }
    // The top can be reached from step n-1 or n-2
    return Math.min(dpPrev, dpPrevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0 || n == 1) {
        // If there's no step or only one step, we can start at step 1 (which is beyond the array) and pay nothing
        return 0;
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 0; // you can start at the only step and climb to the top without paying
    }
    int prev2 = 0; // minimum cost to reach step i-2
    int prev1 = 0; // minimum cost to reach step i-1
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start from step 1 which is already at the top
        return 0;
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        return 0;
    }
    try {
        int n = cost.length;
        int prev2 = 0; // Cost to reach step i-2
        int prev1 = 0; // Cost to reach step i-1
        for (int i = 2; i <= n; i++) {
            int fromPrev1 = prev1 + cost[i - 1];
            int fromPrev2 = prev2 + cost[i - 2];
            int curr = Math.min(fromPrev1, fromPrev2);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid input array", e);
    }
}

