    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) return true;
            }
        }
    }
    return false;
}

