    }
    boolean[] seen = new boolean[required];
    int mask = 0;
    int maskLimit = required - 1;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        int bit = s.charAt(i) - '0';
        mask = ((mask << 1) | bit) & maskLimit;
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                count++;
                if (count == required) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
