public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    // Prevent overflow for large k; for practical constraints k <= 20-22
    if (k >= 31) return false;
    int totalPow = 1 << k;
    if (n - k + 1 < totalPow) return false;

    boolean[] seen = new boolean[totalPow];
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    int count = 1;
    seen[mask] = true;

    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & (totalPow - 1)) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == totalPow) return true;
        }
    }
    return count == totalPow;
}

