public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int leftNeeded = 0; // count of '(' that need a matching ')'
    int insertions = 0; // count of ')' that need a preceding '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            leftNeeded++;
        } else if (c == ')') {
            if (leftNeeded == 0) {
                // No matching '(', need to insert one
                insertions++;
            } else {
                leftNeeded--;
            }
        }
    }
    // Any remaining unmatched '(' need a ')'
    insertions += leftNeeded;
    return insertions;
}

public int minInsertions(String s) {
    int need = 0;      // parentheses needed to match unmatched ')'
    int balance = 0;   // count of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                need++;
            }
        }
    }
    return need + balance;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
