    }
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insertions needed for unmatched ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // match with a previous '('
            } else {
                insertions++; // need an extra '(' before this ')'
            }
        } else {
            // If any non-bracket characters are present, ignore them.
        }
    }
    // Any remaining unmatched '(' require a ')' after them
    return insertions + balance;
}

public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                insertions++;                  // insert a '(' before this ')'
            } else {
                balance--;                     // match the current ')'
            }
        } else {
            throw new IllegalArgumentException(
                "Input string contains invalid character: " + c);
        }
    }
    return insertions + balance;   // remaining '(' need ')'
}

