    int balance = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                needOpen++;
                balance = 0;
            }
        }
    }
    return needOpen + balance;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int m = n / 2; // floor division
    return (n % 2 == 0) ? m * m : m * (m + 1);
}

public int minOperations(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long k = (n + 1L) / 2;            // ceil(n/2)
    long result = k * (n - k);        // k * (n-k)
    return (int) result;              // total operations
}

