    }
}

public int minOperations(int n) {
    if (n <= 1) return 0;
    if ((n & 1) == 0) {
        int half = n >> 1; // n / 2
        return half * half;
    } else {
        int m = (n - 1) >> 1; // (n - 1) / 2
        return m * (m + 1);
    }
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    long k = (n - 1L) / 2L; // floor((n-1)/2)
    long m = n - k - 1L;
    long ops = m * (k + 1L);
    return (int) ops;
}

