    while (true) {
        int next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }

    // Greedy selection of the largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

