        return 0;
    }
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1); // F1
    fibs.add(1); // F2
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    int count = 0;
    int remaining = k;
    while (remaining > 0) {
        // find the largest Fibonacci number <= remaining
        int idx = java.util.Collections.binarySearch(fibs, remaining);
        if (idx < 0) {
            idx = -idx - 2;
        }
        remaining -= fibs.get(idx);
        count++;
    }
    return count;
}

