    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int length = stack.length();
        if (length > 0) {
            char top = stack.charAt(length - 1);
            // Check if c and top are the same letter of opposite cases
            if (Math.abs(c - top) == 32) {
                stack.deleteCharAt(length - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

