public int maxUniqueSplit(String s) {
    int[] max = {0};
    class Solver {
        void solve(int pos, java.util.Set<String> used, int count) {
            if (pos == s.length()) {
                if (count > max[0]) max[0] = count;
                return;
            }
            for (int end = pos + 1; end <= s.length(); end++) {
                String sub = s.substring(pos, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    solve(end, used, count + 1);
                    used.remove(sub);
                }
            }
        }
    }
    new Solver().solve(0, new java.util.HashSet<>(), 0);
    return max[0];
}

