public String getSmallestString(int n, int k) {
    if (k < n || k > n * 26) {
        throw new IllegalArgumentException("k must be between " + n + " and " + (n * 26));
    }
    int remaining = k - n; // extra value beyond all 'a's
    char[] result = new char[n];
    for (int i = n - 1; i >= 0; i--) {
        if (remaining == 0) {
            result[i] = 'a';
            continue;
        }
        int add = Math.min(25, remaining); // we can add at most 25 to 'a' -> 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Validate input: each character value ranges from 1 ('a') to 26 ('z')
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("No possible string with given length and value");
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        // Try the smallest possible character for this position
        for (int val = 1; val <= 26; val++) {
            int remainingSum = k - val;
            // Check if the remaining sum can be distributed among the remaining positions
            if (remainingSum >= remainingPositions * 1 && remainingSum <= remainingPositions * 26) {
                sb.append((char) ('a' + val - 1));
                k = remainingSum;
                break;
            }
        }
    }
    return sb.toString();
}

