public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    // Handle 0 explicitly
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    // Queue for BFS
    Queue<Long> queue = new LinkedList<>();
    // Initialize queue with digits 1 through 9
    for (int d = 1; d <= 9; d++) {
        if (d > high) {
            break;
        }
        if (d >= low) {
            result.add(d);
        }
        queue.offer((long) d);
    }
    // BFS to generate stepping numbers
    while (!queue.isEmpty()) {
        long curr = queue.poll();
        int lastDigit = (int) (curr % 10);
        // Generate next digits: lastDigit-1 and lastDigit+1
        if (lastDigit > 0) {
            long next = curr * 10 + lastDigit - 1;
            if (next <= high) {
                if (next >= low) {
                    result.add((int) next);
                }
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = curr * 10 + lastDigit + 1;
            if (next <= high) {
                if (next >= low) {
                    result.add((int) next);
                }
                queue.offer(next);
            }
        }
    }
    // Sort the result in ascending order
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower   = n % factor;
        long current = (n / factor) % 10;
        long higher  = n / (factor * 10);

        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return (int) count;
}

