public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    do {
        sb.append(value % 10);
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    } while (value > 0);
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Work with absolute value for formatting
    String numStr = Long.toString(Math.abs((long) n));
    int length = numStr.length();

    // Determine the size of the first group (it may be smaller than 3)
    int firstGroupSize = length % 3;
    if (firstGroupSize == 0) {
        firstGroupSize = 3;
    }

    StringBuilder formatted = new StringBuilder();
    // Append the first group without a preceding dot
    formatted.append(numStr, 0, firstGroupSize);

    // Append the remaining groups, each preceded by a dot
    for (int i = firstGroupSize; i < length; i += 3) {
        formatted.append('.');
        formatted.append(numStr, i, i + 3);
    }

    // Add negative sign if original number was negative
    if (negative) {
        formatted.insert(0, '-');
    }

    return formatted.toString();
}

