public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal + maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 2; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int[] row : memo) {
        java.util.Arrays.fill(row, -1);
    }
    class Solver {
        int dfs(int lastIdx, int mask) {
            if (mask == fullMask) return 1;
            int memoVal = memo[mask][lastIdx];
            if (memoVal != -1) return memoVal;
            int ans = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!isSquare[A[lastIdx] + A[next]]) continue;
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) continue;
                ans += dfs(next, mask | (1 << next));
            }
            memo[mask][lastIdx] = ans;
            return ans;
        }
    }
    Solver solver = new Solver();
    int total = 0;
    for (int start = 0; start < n; start++) {
        if (start > 0 && A[start] == A[start - 1]) continue;
        int firstMask = 1 << start;
        total += solver.dfs(start, firstMask);
    }
    return total;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    // Build frequency map
    java.util.Map<Integer,Integer> freqMap = new java.util.HashMap<>();
    for (int num : A) freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
    int m = freqMap.size();
    int[] vals = new int[m];
    int[] countsInit = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer,Integer> e : freqMap.entrySet()) {
        vals[idx] = e.getKey();
        countsInit[idx] = e.getValue();
        idx++;
    }
    // Build adjacency list based on perfect square sums
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(m);
    for (int i = 0; i < m; i++) {
        java.util.List<Integer> list = new java.util.ArrayList<>();
        for (int j = 0; j < m; j++) {
            if (i == j) continue;
            int sum = vals[i] + vals[j];
            int r = (int) Math.sqrt(sum);
            if (r * r == sum) list.add(j);
        }
        adj.add(list);
    }
    java.util.Map<String,Integer> memo = new java.util.HashMap<>();
    class Solver {
        int[] counts;
        Solver(int[] counts) { this.counts = counts; }
        int dfs(int prevIdx) {
            StringBuilder sb = new StringBuilder();
            sb.append(prevIdx).append('|');
            for (int c : counts) sb.append(c).append(',');
            String key = sb.toString();
            if (memo.containsKey(key)) return memo.get(key);
            int total = 0;
            boolean allZero = true;
            for (int c : counts) if (c > 0) { allZero = false; break; }
            if (allZero) {
                total = 1;
            } else {
                if (prevIdx == -1) {
                    for (int i = 0; i < m; i++) {
                        if (counts[i] == 0) continue;
                        counts[i]--;
                        total += dfs(i);
                        counts[i]++;
                    }
                } else {
                    for (int next : adj.get(prevIdx)) {
                        if (counts[next] == 0) continue;
                        counts[next]--;
                        total += dfs(next);
                        counts[next]++;
                    }
                }
            }
            memo.put(key, total);
            return total;
        }
    }
    Solver solver = new Solver(countsInit.clone());
    return solver.dfs(-1);
}

public static int squarePermutations(int[] A) {
    int N = A.length;
    if (N == 0) return 1;
    int fullMask = (1 << N) - 1;
    int[][] dp = new int[1 << N][N + 1];
    for (int i = 0; i < dp.length; i++) {
        java.util.Arrays.fill(dp[i], -1);
    }
    java.util.HashSet<Integer> memoKey = new java.util.HashSet<>();

    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<Integer, Integer, Integer>() {
        @Override
        public Integer apply(Integer mask, Integer lastIdx) {
            if (mask == fullMask) {
                return 1;
            }
            int dpIdx = lastIdx == N ? N : lastIdx;
            if (dp[mask][dpIdx] != -1) {
                return dp[mask][dpIdx];
            }
            int res = 0;
            java.util.HashSet<Integer> seen = new java.util.HashSet<>();
            for (int i = 0; i < N; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (lastIdx == N || isSquare(A[i] + A[lastIdx])) {
                    if (!seen.contains(A[i])) {
                        seen.add(A[i]);
                        res += dfs.apply(mask | (1 << i), i);
                    }
                }
            }
            dp[mask][dpIdx] = res;
            return res;
        }
    };

    return dfs.apply(0, N);
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    boolean[][] valid = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int s = (int) Math.sqrt(sum);
                valid[i][j] = (s * s == sum);
            }
        }
    }
    int fullMask = (1 << n) - 1;
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.IntFunction<java.util.IntBinaryOperator> keyFunc = (i) -> (mask) -> ((long) mask << 32) | i;

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int ptr) {
            int mask = (int) (ptr >>> 32);
            int last = (int) ptr;
            long memoKey = ((long) mask << 32) | (last & 0xffffffffL);
            if (memo.containsKey(memoKey)) return memo.get(memoKey);
            if (mask == fullMask) return 1;
            int total = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                if (last == -1 || valid[last][i]) {
                    total += dfs.applyAsInt(((mask | (1 << i)) << 32) | i);
                }
            }
            memo.put(memoKey, total);
            return total;
        }
    };

    int result = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0 && A[i] == A[i - 1]) continue;
        result += dfs.applyAsInt((((1 << i) << 32) | i));
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[] used = new boolean[n];
    java.util.concurrent.atomic.AtomicLong count = new java.util.concurrent.atomic.AtomicLong(0);

    java.util.function.BiConsumer<Integer, java.util.function.Consumer<Long>> dfs = new java.util.function.BiConsumer<>() {
        @Override
        public void accept(int pos, java.util.function.Consumer<Long> consumer) {
            if (pos == n) {
                consumer.accept(1L);
                return;
            }
            long localSum = 0;
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
                if (pos > 0) {
                    int sum = arr[pos - 1] + arr[i];
                    int r = (int) Math.sqrt(sum);
                    if (r * r != sum) continue;
                }
                used[i] = true;
                dfs.accept(pos + 1, len -> localSum += len);
                used[i] = false;
            }
            consumer.accept(localSum);
        }
    };

    dfs.accept(0, count::addAndGet);
    return (int) count.get();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

