    } catch (Exception e) {
        // In case of unexpected runtime issues, return 0 as a safe default
        return 0;
    }
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    int row = 0, col = 0;
    boolean up = true;

    while (index < m * n) {
        res[index++] = mat[row][col];
        if (up) {
            if (col == n - 1) { // hit right edge
                row++;
                up = false;
            } else if (row == 0) { // hit top edge
                col++;
                up = false;
            } else { // move up-right
                row--;
                col++;
            }
        } else { // down-left
            if (row == m - 1) { // hit bottom edge
                col++;
                up = true;
            } else if (col == 0) { // hit left edge
                row++;
                up = true;
            } else { // move down-left
                row++;
                col--;
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        if ((d & 1) == 0) { // even diagonal: traverse from bottom to top
            int i = Math.min(d, m - 1);
            int j = d - i;
            while (i >= 0 && j < n) {
                result[index++] = mat[i][j];
                i--;
                j++;
            }
        } else { // odd diagonal: traverse from top to bottom
            int j = Math.min(d, n - 1);
            int i = d - j;
            while (j >= 0 && i < m) {
                result[index++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

