public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(sum, m - 1);
        if (sum % 2 == 0) {
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
