        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int total = m + n - 1;
    for (int k = 0; k < total; k++) {
        if (k % 2 == 0) {
            // move from bottom to top
            int i = Math.min(k, m - 1);
            int j = k - i;
            while (i >= 0 && j < n) {
                result[index++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            // move from top to bottom
            int j = Math.min(k, n - 1);
            int i = k - j;
            while (j >= 0 && i < m) {
                result[index++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] c = String.valueOf(n).toCharArray();
    int[] d = new int[c.length];
    for (int i = 0; i < c.length; i++) {
        d[i] = c[i] - '0';
    }

    // Find the first index from the end where d[i] < d[i+1]
    int i = d.length - 2;
    while (i >= 0 && d[i] >= d[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit greater than d[i] in the suffix
    int j = d.length - 1;
    while (d[j] <= d[i]) {
        j--;
    }

    // Swap
    int tmp = d[i];
    d[i] = d[j];
    d[j] = tmp;

    // Reverse the suffix
    int l = i + 1;
    int r = d.length - 1;
    while (l < r) {
        tmp = d[l];
        d[l] = d[r];
        d[r] = tmp;
        l++;
        r--;
    }

    // Convert back to integer, check for overflow
    long result = 0;
    for (int val : d) {
        result = result * 10 + val;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }
    return (int) result;
}

