public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 9; i >= 1; i--) {
        if (i <= n) {
            stack.push(i);
        }
    }
    while (!stack.isEmpty()) {
        int current = stack.pop();
        result.add(current);
        for (int d = 9; d >= 0; d--) {
            int next = current * 10 + d;
            if (next <= n) {
                stack.push(next);
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    if (n <= 0) return res;
    for (int start = 1; start <= 9 && res.size() < n; start++) {
        int curr = start;
        while (curr <= n && res.size() < n) {
            res.add(curr);
            if (curr * 10 <= n) {
                curr *= 10;
            } else {
                if (curr % 10 != 9 && curr + 1 <= n) {
                    curr++;
                } else {
                    curr /= 10;
                    while (curr % 10 == 9 && curr != 0) {
                        curr /= 10;
                    }
                    if (curr == 0) break;
                    curr++;
                }
            }
        }
    }
    return res;
}

