}

public static int calculateUniqueSum(int[] nums) {
    // If the input array is null, return 0 as there are no unique elements to sum.
    if (nums == null) {
        return 0;
    }

    try {
        java.util.Map<Integer, Integer> frequencyMap = new java.util.HashMap<>();

        // Count occurrences of each number.
        for (int num : nums) {
            // Using merge to handle both insertion and increment in a single expression.
            frequencyMap.merge(num, 1, Integer::sum);
        }

        long uniqueSum = 0L; // Use long for intermediate sum to detect overflow.

        // Sum numbers that occur exactly once.
        for (java.util.Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            if (entry.getValue() == 1) {
                uniqueSum += entry.getKey();

                // Detect overflow: if the sum exceeds integer bounds, throw an exception.
                if (uniqueSum > Integer.MAX_VALUE || uniqueSum < Integer.MIN_VALUE) {
                    throw new ArithmeticException("Sum of unique elements overflows integer range.");
                }
            }
        }

        return (int) uniqueSum;
    } catch (RuntimeException e) {
        // For unexpected runtime exceptions, wrap and rethrow as an IllegalStateException
        // to avoid suppressing bugs while still providing a clear error message.
        throw new IllegalStateException("Failed to calculate unique sum due to an unexpected error.", e);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (var entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int best = Integer.MAX_VALUE;
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            int cand = dp[i - square] + 1;
            if (cand < best) {
                best = cand;
            }
        }
        dp[i] = best;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Handle non-positive input
    if (n <= 0) {
        return 0;
    }

    // dp[i] will hold the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0; // Base case: 0 requires 0 perfect squares

    for (int i = 1; i <= n; i++) {
        // Initialize with a value larger than any possible answer
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            if (dp[j - square] != Integer.MAX_VALUE && dp[j - square] + 1 < dp[j]) {
                dp[j] = dp[j - square] + 1;
            }
        }
    }
    return dp[n];
}

